#include <string>
#include <vector>

struct Input { float mouseX{ -1 }, mouseY{ -1 }; bool mouseDown{ false }; };

class Ui
{
public:
    void beginFrame(const Input& input) {}
    void endFrame() {}
    void label(const std::string& text) {}
    bool button(const std::string& label) { return false; }
    bool checkbox(const std::string& label, bool* value) { return false; }
    void pushId(const std::string& id) {}
    void popId() {}
    const std::vector<std::string>& drawList() const { return m_draw; }
private:
    std::vector<std::string> m_draw;
};

solution.solution.cpp:
#include <string>
#include <vector>

struct Input { float mouseX{ -1 }, mouseY{ -1 }; bool mouseDown{ false }; };

class Ui
{
public:
    void beginFrame(const Input& input)
    {
        m_pressed = input.mouseDown && !m_wasDown;
        m_released = !input.mouseDown && m_wasDown;
        m_wasDown = input.mouseDown;
        m_input = input;
        m_y = 0;
        m_draw.clear();
        m_stack.clear();
        m_activeSeen = false;
    }

    void endFrame()
    {
        if (!m_activeSeen || m_released) m_active.clear();
    }

    void label(const std::string& text)
    {
        m_draw.push_back("text " + shown(text));
        advance();
    }

    bool button(const std::string& label)
    {
        bool hot{ false };
        const bool clicked{ behave(label, hot) };
        m_draw.push_back("button " + shown(label) + marks(label, hot));
        advance();
        return clicked;
    }

    bool checkbox(const std::string& label, bool* value)
    {
        bool hot{ false };
        const bool clicked{ behave(label, hot) };
        if (clicked && value) *value = !*value;
        m_draw.push_back("checkbox " + shown(label) + ((value && *value) ? " [x]" : " [ ]") + marks(label, hot));
        advance();
        return clicked;
    }

    void pushId(const std::string& id) { m_stack.push_back(id); }
    void popId() { if (!m_stack.empty()) m_stack.pop_back(); }

    const std::vector<std::string>& drawList() const { return m_draw; }

private:
    static std::string shown(const std::string& label)
    {
        const auto at{ label.find("##") };
        return at == std::string::npos ? label : label.substr(0, at);
    }

    std::string idOf(const std::string& label) const
    {
        const auto at{ label.find("###") };
        std::string id;
        for (const std::string& s : m_stack) id += s + "/";
        return id + (at == std::string::npos ? label : label.substr(at));
    }

    bool behave(const std::string& label, bool& hot)
    {
        const std::string id{ idOf(label) };
        hot = m_input.mouseX >= 0 && m_input.mouseX < 100 && m_input.mouseY >= m_y && m_input.mouseY < m_y + 20;
        if (m_pressed && hot && m_active.empty()) m_active = id;
        bool clicked{ false };
        if (m_active == id)
        {
            m_activeSeen = true;
            if (m_released) clicked = hot;
        }
        return clicked;
    }

    std::string marks(const std::string& label, bool hot) const
    {
        std::string m;
        if (hot) m += " hot";
        if (!m_active.empty() && m_active == idOf(label) && !m_released) m += " active";
        return m;
    }

    void advance() { m_y += 24; }

    Input m_input;
    bool m_wasDown{ false };
    bool m_pressed{ false };
    bool m_released{ false };
    bool m_activeSeen{ false };
    float m_y{ 0 };
    std::string m_active;
    std::vector<std::string> m_stack;
    std::vector<std::string> m_draw;
};

unitTests:
using Lines = std::vector<std::string>;
bool frame(Ui& ui, Input in, bool* box = nullptr) {
    ui.beginFrame(in);
    ui.label("Stones");
    const bool clicked = ui.button("Add");
    if (box) ui.checkbox("Show##box", box);
    ui.endFrame();
    return clicked;
}
TEST("layout and drawing") { Ui ui; bool b = false; frame(ui, Input{}, &b); CHECK_EQ(ui.drawList(), (Lines{ "text Stones", "button Add", "checkbox Show [ ]" })); }
TEST("hover") { Ui ui; frame(ui, Input{ 50, 30, false }); CHECK_EQ(ui.drawList()[1], std::string("button Add hot")); }
TEST("press, hold, release") {
    Ui ui;
    CHECK(!frame(ui, Input{ 50, 30, false }));
    CHECK(!frame(ui, Input{ 50, 30, true })); CHECK_EQ(ui.drawList()[1], std::string("button Add hot active"));
    CHECK(!frame(ui, Input{ 300, 30, true })); CHECK_EQ(ui.drawList()[1], std::string("button Add active"));
    CHECK(!frame(ui, Input{ 300, 30, false })); CHECK_EQ(ui.drawList()[1], std::string("button Add"));
}
TEST("a real click") { Ui ui; frame(ui, Input{ 50, 30, true }); CHECK(frame(ui, Input{ 50, 30, false })); }
TEST("checkbox toggles") { Ui ui; bool b = false; frame(ui, Input{ 10, 50, true }, &b); frame(ui, Input{ 10, 50, false }, &b); CHECK(b); CHECK_EQ(ui.drawList()[2], std::string("checkbox Show [x] hot")); }
TEST("loop items need ids") {
    Ui ui; int clicks[3] = { 0, 0, 0 };
    for (int f = 0; f < 2; ++f) {
        ui.beginFrame(Input{ 10, 26, f == 0 });
        for (int i = 0; i < 3; ++i) { ui.pushId(std::to_string(i)); if (ui.button("Delete")) clicks[i]++; ui.popId(); }
        ui.endFrame();
    }
    CHECK_EQ(clicks[0], 0); CHECK_EQ(clicks[1], 1); CHECK_EQ(clicks[2], 0);
}
TEST("a widget that disappears loses active") {
    Ui ui;
    frame(ui, Input{ 50, 30, true });
    ui.beginFrame(Input{ 50, 30, true }); ui.label("nothing else"); ui.endFrame();
    CHECK(!frame(ui, Input{ 50, 30, false }));
}

